$ErrorActionPreference='Stop'; Add-Type -AssemblyName System.Drawing
$fig=Join-Path $PSScriptRoot 'figures'; $font=New-Object Drawing.Font('Arial',12); $title=New-Object Drawing.Font('Arial',18,([Drawing.FontStyle]::Bold)); $colors=@('#265c8c','#c6702d','#2f7d79')
function DrawChart($name,$heading,$groups,$series,$max=100,$step=20){$W=1200;$H=700;$bmp=New-Object Drawing.Bitmap($W,$H);$g=[Drawing.Graphics]::FromImage($bmp);$g.Clear([Drawing.Color]::White);$g.DrawString($heading,$title,[Drawing.Brushes]::Black,35,25);$L=125;$T=95;$R=1120;$B=590;$g.DrawLine([Drawing.Pens]::Black,$L,$T,$L,$B);$g.DrawLine([Drawing.Pens]::Black,$L,$B,$R,$B);for($t=0;$t -le $max;$t+=$step){$y=$B-($t/$max)*($B-$T);$g.DrawLine([Drawing.Pens]::LightGray,$L,$y,$R,$y);$g.DrawString("$t",$font,[Drawing.Brushes]::Black,80,$y-8)};$bw=60;$n=$groups.Count;for($i=0;$i -lt $n;$i++){ $cx=$L+($i+.5)*($R-$L)/$n;$g.DrawString($groups[$i],$font,[Drawing.Brushes]::Black,$cx-55,$B+15);for($j=0;$j -lt $series.Count;$j++){ $v=$series[$j].v[$i];$h=$v/$max*($B-$T);$x=$cx+($j-($series.Count-1)/2)*($bw+8)-$bw/2;$y=$B-$h;$g.FillRectangle((New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml($colors[$j]))),$x,$y,$bw,$h);$g.DrawString(('{0:0.##}'-f $v),$font,[Drawing.Brushes]::Black,$x,$y-24)}};for($j=0;$j -lt $series.Count;$j++){ $y=55+$j*24;$g.FillRectangle((New-Object Drawing.SolidBrush([Drawing.ColorTranslator]::FromHtml($colors[$j]))),870,$y,15,15);$g.DrawString($series[$j].n,$font,[Drawing.Brushes]::Black,892,$y-2)};$g.Dispose();$bmp.SetResolution(300,300);$bmp.Save((Join-Path $fig "$name.png"),[Drawing.Imaging.ImageFormat]::Png);$bmp.Dispose()}
function DrawSvg($name,$heading,$groups,$series,$max=100,$step=20){$c=@('#265c8c','#c6702d','#2f7d79');$p=@("<svg xmlns='http://www.w3.org/2000/svg' width='1200' height='700'><rect width='100%' height='100%' fill='white'/><text x='35' y='50' font-family='Arial' font-size='24' font-weight='bold'>$heading</text>");$L=125;$T=95;$R=1120;$B=590;for($t=0;$t -le $max;$t+=$step){$y=$B-($t/$max)*($B-$T);$p+="<line x1='$L' y1='$y' x2='$R' y2='$y' stroke='#ddd'/><text x='80' y='$($y+5)' font-family='Arial' font-size='14'>$t</text>"};$bw=60;$n=$groups.Count;for($i=0;$i -lt $n;$i++){ $cx=$L+($i+.5)*($R-$L)/$n;$p+="<text x='$($cx-55)' y='625' font-family='Arial' font-size='14'>$($groups[$i])</text>";for($j=0;$j -lt $series.Count;$j++){ $v=$series[$j].v[$i];$h=$v/$max*($B-$T);$x=$cx+($j-($series.Count-1)/2)*($bw+8)-$bw/2;$y=$B-$h;$p+="<rect x='$x' y='$y' width='$bw' height='$h' fill='$($c[$j])'/><text x='$x' y='$($y-8)' font-family='Arial' font-size='13'>$('{0:0.##}'-f $v)</text>"}};$p+='</svg>';[IO.File]::WriteAllText((Join-Path $fig "$name.svg"),($p-join''),(New-Object Text.UTF8Encoding($false)))}
DrawChart 'figure2a_retrieval_selection' 'Retrieval Ablation - Selection Recall@4 (%)' @('R0','R1','R2','R3') @([pscustomobject]@{n='Recall@4';v=@(95,95,97.5,100)});DrawSvg 'figure2a_retrieval_selection' 'Retrieval Ablation - Selection Recall@4 (%)' @('R0','R1','R2','R3') @([pscustomobject]@{n='Recall@4';v=@(95,95,97.5,100)})
DrawChart 'figure2b_retrieval_downstream' 'Retrieval Ablation - Confirmation Full Recall (%)' @('R0','R3') @([pscustomobject]@{n='Full Recall';v=@(80,76.67)});DrawSvg 'figure2b_retrieval_downstream' 'Retrieval Ablation - Confirmation Full Recall (%)' @('R0','R3') @([pscustomobject]@{n='Full Recall';v=@(80,76.67)})
DrawChart 'figure3a_rq4_quality_reliability' 'RQ4 Debate - Quality and Usability (%)' @('Full Recall (N=80 paired)','Usability (N=100/condition)') @([pscustomobject]@{n='C2';v=@(83.75,88)},[pscustomobject]@{n='C4';v=@(81.25,80)});DrawSvg 'figure3a_rq4_quality_reliability' 'RQ4 Debate - Quality and Usability (%)' @('Full Recall (N=80 paired)','Usability (N=100/condition)') @([pscustomobject]@{n='C2';v=@(83.75,88)},[pscustomobject]@{n='C4';v=@(81.25,80)})
