DrawChart 'figure5_a3_quality_usability' 'A3 v1.3 - Quality and Usability (%)' @('Strict Full Recall (N=76 paired)','Usability (N=100/condition)') @([pscustomobject]@{n='M1';v=@(73.7,96)},[pscustomobject]@{n='M2';v=@(81.6,78)});DrawSvg 'figure5_a3_quality_usability' 'A3 v1.3 - Quality and Usability (%)' @('Strict Full Recall (N=76 paired)','Usability (N=100/condition)') @([pscustomobject]@{n='M1';v=@(73.7,96)},[pscustomobject]@{n='M2';v=@(81.6,78)})
DrawChart 'figure5_a3_latency' 'A3 v1.3 - Mean Latency (seconds)' @('M1','M2') @([pscustomobject]@{n='Mean latency';v=@(115.12,391.46)}) 400 100;DrawSvg 'figure5_a3_latency' 'A3 v1.3 - Mean Latency (seconds)' @('M1','M2') @([pscustomobject]@{n='Mean latency';v=@(115.12,391.46)}) 400 100
# Repaint A3 latency with fixed major-tick coordinates (0, 100, 200, 300, 400).
$W=1200;$H=700;$bmp=New-Object Drawing.Bitmap($W,$H);$g=[Drawing.Graphics]::FromImage($bmp);$g.Clear([Drawing.Color]::White);$g.DrawString('A3 v1.3 - Mean Latency (seconds)',$title,[Drawing.Brushes]::Black,35,25);$L=125;$T=95;$R=1120;$B=590;foreach($tick in @(0,100,200,300,400)){ $yy=$B-($tick/400.0)*($B-$T);$g.DrawLine([Drawing.Pens]::LightGray,$L,$yy,$R,$yy);$g.DrawString([string]$tick,$font,[Drawing.Brushes]::Black,80,$yy-8)};$g.DrawLine([Drawing.Pens]::Black,$L,$T,$L,$B);$g.DrawLine([Drawing.Pens]::Black,$L,$B,$R,$B);$vals=@(115.12,391.46);$labs=@('M1','M2');for($i=0;$i -lt 2;$i++){ $x=350+$i*520;$hh=$vals[$i]/400.0*($B-$T);$yy=$B-$hh;$g.FillRectangle((New-Object Drawing.SolidBrush([Drawing.Color]::FromArgb(38,92,140))),$x,$yy,60,$hh);$g.DrawString(('{0:0.##}'-f $vals[$i]),$font,[Drawing.Brushes]::Black,$x,$yy-24);$g.DrawString($labs[$i],$font,[Drawing.Brushes]::Black,$x-5,$B+15)};$g.Dispose();$bmp.SetResolution(300,300);$bmp.Save((Join-Path $fig 'figure5_a3_latency.png'),[Drawing.Imaging.ImageFormat]::Png);$bmp.Dispose()
# Compact two-row architecture for portrait reports
$W=1200;$H=780;$bmp=New-Object Drawing.Bitmap($W,$H);$g=[Drawing.Graphics]::FromImage($bmp);$g.Clear([Drawing.Color]::White);$g.DrawString('TCM-focused MediRAG-Judge pipeline',$title,[Drawing.Brushes]::Black,35,25);$top=@('Question','Planner','Retrieval','Specialist Agents','Debate / Consensus');$bottom=@('Evidence Judge','Safety Judge','Conflict Judge','Confidence Judge');for($i=0;$i-lt$top.Count;$i++){ $x=55+$i*225;$g.FillRectangle([Drawing.Brushes]::AliceBlue,$x,150,180,70);$g.DrawRectangle([Drawing.Pens]::DarkSlateGray,$x,150,180,70);$g.DrawString($top[$i],$font,[Drawing.Brushes]::Black,$x+12,178);if($i-lt$top.Count-1){$g.DrawLine([Drawing.Pens]::DarkSlateGray,$x+180,185,$x+220,185)}};for($i=0;$i-lt$bottom.Count;$i++){ $x=150+$i*250;$g.FillRectangle([Drawing.Brushes]::MistyRose,$x,390,190,70);$g.DrawRectangle([Drawing.Pens]::DarkSlateGray,$x,390,190,70);$g.DrawString($bottom[$i],$font,[Drawing.Brushes]::Black,$x+14,418);if($i-lt$bottom.Count-1){$g.DrawLine([Drawing.Pens]::DarkSlateGray,$x+190,425,$x+242,425)}};$g.DrawLine([Drawing.Pens]::DarkSlateGray,955,220,955,330);$g.DrawLine([Drawing.Pens]::DarkSlateGray,955,330,245,330);$g.DrawLine([Drawing.Pens]::DarkSlateGray,245,330,245,390);$g.FillRectangle([Drawing.Brushes]::AliceBlue,390,570,420,75);$g.DrawRectangle([Drawing.Pens]::DarkSlateGray,390,570,420,75);$g.DrawString('Integrated Response',$font,[Drawing.Brushes]::Black,520,598);$g.DrawLine([Drawing.Pens]::DarkSlateGray,625,460,625,570);$g.DrawString('Generation / reasoning',$font,[Drawing.Brushes]::DarkSlateGray,55,105);$g.DrawString('Governance / judging',$font,[Drawing.Brushes]::DarkSlateGray,150,345);$g.DrawString('Source-grounded safety flags | evidence-supported caution assessment | evidence confidence | response reliability indicator',$font,[Drawing.Brushes]::DarkSlateGray,55,700);$g.Dispose();$bmp.SetResolution(300,300);$bmp.Save((Join-Path $fig 'figure1_system_architecture.png'),[Drawing.Imaging.ImageFormat]::Png);$bmp.Dispose()
